        norm=torch_to_axlearn(src.LayerNorm),
        dropout={},
    )
    if dst_layer is None or isinstance(dst_layer.pos_emb, LearnedPositionalEmbedding):
        dst["pos_emb"]["weight"] = dst["pos_emb"]["weight"][None, ...]
    return dst


