            for ex in examples:
                yield ex

        ds = tf.data.Dataset.from_generator(
            gen,
            output_signature={
                "a": tf.TensorSpec(shape=(1,), dtype=tf.int32),
                "b": tf.TensorSpec(shape=(2, 1), dtype=tf.int32),
                "c": tf.TensorSpec(shape=(2, 1), dtype=tf.int32),
            },
        )

