    def test_rekey_does_not_map_falsey_reference_keys_with_none_default(self):
        ds = self._ds_fn()
        ds = rekey({"new_key1": "key1", "new_key2": None}, default_value=None)(ds)
        for ix, el in enumerate(ds):
